  const PIN = () => `<svg viewBox="-20 -44 40 48"><path d="M0 2 C-4 -10 -16 -18 -16 -28 A16 16 0 0 1 16 -28 C16 -18 4 -10 0 2 Z" fill="#d9745e"/><circle cx="0" cy="-28" r="6" fill="#fbf2e2"/></svg>`;
