        const box = document.createElement('i'); box.className = 'pc'; const bw = bb.width * k, bh = bb.height * k;
        box.style.cssText = `left:0;top:0;width:${bw.toFixed(1)}px;height:${bh.toFixed(1)}px`;
        box.innerHTML = `<svg viewBox="${bb.x} ${bb.y} ${bb.width} ${bb.height}">${cab.outerHTML.replace(/class="fx-cab"/, '')}</svg>`;
        host.parentElement.appendChild(box); par.remove();
